package com.substring.auth.app.auth.config;
import com.substring.auth.app.auth.entities.User; import com.substring.auth.app.auth.repositories.UserRepository; import com.substring.auth.app.auth.services.impl.JwtService; import io.jsonwebtoken.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.UUID;
@Component @RequiredArgsConstructor public class JwtAuthenticationFilter extends OncePerRequestFilter{
 private final JwtService jwt;private final UserRepository users;
 protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{String t=h.substring(7).trim();if(jwt.isAccessToken(t)){var p=jwt.parse(t);UUID id=UUID.fromString(p.getPayload().getSubject());users.findById(id).filter(User::isEnabled).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getEmail(),null,u.getAuthorities())));}}catch(ExpiredJwtException e){r.setAttribute("auth_error","Access token expired");}catch(Exception e){r.setAttribute("auth_error","Invalid access token");}}c.doFilter(r,s);}
 protected boolean shouldNotFilter(HttpServletRequest r){String p=r.getRequestURI();return p.startsWith("/oauth2")||p.startsWith("/login/oauth2")||p.startsWith("/actuator");}
}
